Definition rs_W4 (lo : Z) (sp : word) (P stb out n : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -144); (stb, stb + SZ_SPCI_STATE); (P + 456, P + 480); (out, out + n); (P + 424, P + 432)]%Z.

Definition rs_read1_post (rax : word) (sp : word) (gp tp : word) (tot P : Z) (s6x s10 s11 : word)
