  fun ms' => exists rax' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
    let k := rs_take sds n in
    ms' = MS (mkR rax' (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0' t1' t2' (wz tot) (wz (P + O_H_EC)) a0' a1' a2' a3' a4' a5' a6' a7'
