              F (Z_to_bv 64 RS_CMP) fc None m' (seg_rom rsegs)
    /\ munch (rs_W4 lo sp P stb (fb_out FB) n) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -144)
    /\ StateBlock LB m' stb (P + 384) implb (rs_state (mkST (mkSPC VP_SPCI_STATE 1 1 1) 0 Fs STREAM_EOF nr nb) sds n) (skipn (Z.to_nat k) sds)
    /\ rw_cells rsegs m' (fb_out FB) [CB (Z.to_nat k) (firstn (Z.to_nat k) sds); CB (Z.to_nat (n - k)) (skipn (Z.to_nat k) junk)]
    /\ rw_cells rsegs m' (P + O_H_EC) (ErrCodeCells (if zlength sds =? 0 then EC_ts_eof else EC_clear))
    /\ rw_cells rsegs m' (P + O_H_FB) (FlatBufCells (mkFB (fb_begin FB) (fb_in FB) (fb_out FB + k) (fb_last FB) (fb_end FB)))
    /\ XStatics m' /\ MiscVt48 m'
    /\ rw_cells rsegs m' (bv_unsigned sp + -144) [CB 8 j8]
    /\ rw_cells rsegs m' (bv_unsigned sp + -136) t1c
    /\ rw_cells rsegs m' (bv_unsigned sp + -112) [CB 1 [b8 1]; CB 7 j7; C8 (wz (fb_out FB)); C8 (wz n)]
    /\ rw_cells rsegs m' (bv_unsigned sp + -88) (map C8 (rs_sv s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra))
    /\ rw_cells rsegs m' (P + O_H_STREAM) (BasicStreamCells stb).

Definition rs_read1_stmt : Prop :=
  forall rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s9x s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v ra t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P tot stb implb nr nb n : Z) (LB : list block) (Fs FB : fbv) (sds junk j8 j7 : list byte) (t1c : list cell),
  (* [comment removed for export] *)
  rw_cells rsegs m (P + O_H_FB) (FlatBufCells FB) -> fb_last FB = fb_out FB + n ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB -> fb_in FB <= fb_out FB -> fb_last FB <= fb_end FB -> fb_end FB <= hceil ->
  rw_cells rsegs m (fb_out FB) [CB (Z.to_nat n) junk] -> 512 <= n <= 65536 ->
  (* [comment removed for export] *)
  rw_cells rsegs m (bv_unsigned sp + -144) [CB 8 j8] ->
  rw_cells rsegs m (bv_unsigned sp + -136) t1c -> cells_size t1c = 24%nat ->
  rw_cells rsegs m (bv_unsigned sp + -112) [CB 1 [b8 1]; CB 7 j7; C8 (wz (fb_out FB)); C8 (wz n)] ->
  rw_cells rsegs m (bv_unsigned sp + -88) (map C8 (rs_sv s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  (* [comment removed for export] *)
  rw_cells rsegs m (P + O_H_EC) (ErrCodeCells EC_clear) ->
  rw_cells rsegs m (P + O_H_STREAM) (BasicStreamCells stb) ->
  StateBlock LB m stb (P + 384) implb (mkST (mkSPC VP_SPCI_STATE 1 1 1) 0 Fs STREAM_EOF nr nb) sds ->
  0 <= nr -> nr + 1 < 2^63 -> 0 <= nb -> nb + zlength sds < 2^63 ->
  (fb_out FB + n <= stb \/ stb + SZ_SPCI_STATE <= fb_out FB) ->
  (fb_out FB + n <= fb_begin Fs \/ fb_end Fs <= fb_out FB) ->
  (fb_out FB + n <= 0x10000 \/ 0xb4000 <= fb_out FB) ->
  (fb_end Fs <= stb \/ stb + SZ_SPCI_STATE <= fb_begin Fs) ->
  XStatics m -> MiscVt48 m ->
  stk rsegs m lo (bv_unsigned sp + -144) -> lo + 320 <= bv_unsigned sp -> hceil <= lo -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 480 <= 2^64 -> P mod 8 = 0 -> bv_unsigned sp mod 8 = 0 -> 0 <= tot < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (rs_read1_post rax sp gp tp tot P s6x s10 s11 F fc m lo stb implb nr nb LB Fs sds junk FB n j8 t1c j7 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)
    (rs_ms RS_DBPRET rax sp gp tp t0 t1 t2 tot P a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s9x s10 s11 t3 t4 t5 t6 F fc m).
