(* [comment removed for export] *)
(* [comment removed for export] *)
Definition LOC_RS_EOS : Z := 0x7bd20.      (* [comment removed for export] *)

(* [comment removed for export] *)
Definition rs_eof_c (c : pcore) : pcore := if pc_state c =? 0 then c else snd (peof_res c).
Definition rs_eof_E (c : pcore) : ecv := if pc_state c =? 0 then EC_http_loc HE_END_OF_STREAM LOC_RS_EOS else fst (peof_res c).
Definition rs_eof_g (c : pcore) (g : bool) : bool := if pc_state c =? 0 then true else peof_assigns c || g.

Lemma peof_res_cases : forall c, pcore_ok c -> pc_state c <> 0 ->
  (exists loc, peof_res c = (EC_http_loc HE_PARTIAL_MESSAGE loc, c) /\ (loc = LOC_PEOF_1 \/ loc = LOC_PEOF_2))
  \/ (peof_res c = (EC_clear, snd (peof_res c)) /\ pc_state (snd (peof_res c)) = 11).
Proof.
  intros c OK NZ. unfold peof_res.
  destruct (pc_state c <=? 2) eqn:L2; [left; exists LOC_PEOF_1; split; [reflexivity | left; reflexivity]|].
  destruct (peof_body_flags c).
  - destruct (pc_state c =? 11) eqn:E11.
    + right. split; [reflexivity|]. cbn. apply Z.eqb_eq in E11. exact E11.
    + left. exists LOC_PEOF_2. split; [reflexivity | right; reflexivity].
  - right. split; [reflexivity|]. cbn. reflexivity.
Qed.

