Definition rs_W5 (lo : Z) (sp : word) (P : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (P + 456, P + 480); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition rs_eof_post (ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo tot P : Z) (c : pcore) (pad7 pad2 : list byte) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0v s1v (wz tot) a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch (rs_W5 lo sp P) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' P (ParserCoreCells (rs_eof_c c) pad7 pad2)
      /\ rw_cells rsegs m' (P + O_H_EC) (ErrCodeCells (rs_eof_E c))
      /\ HttpCat m' (rs_eof_g c g) /\ XStatics m'.

Definition rs_eof_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s6x s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P tot : Z) (c : pcore) (pad7 pad2 : list byte) (g : bool) (j8 : list byte) (t1c optc : list cell),
  rw_cells rsegs m (P + O_H_EC) (ErrCodeCells EC_ts_eof) ->
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  HttpCat m g -> XStatics m -> MiscVt48 m ->
  rw_cells rsegs m (bv_unsigned sp + -144) [CB 8 j8] ->
  rw_cells rsegs m (bv_unsigned sp + -136) t1c -> cells_size t1c = 24%nat ->
  rw_cells rsegs m (bv_unsigned sp + -112) optc -> cells_size optc = 24%nat ->
  rw_cells rsegs m (bv_unsigned sp + -88) (map C8 (rs_sv s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  stk rsegs m lo (bv_unsigned sp + -144) -> lo + 224 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 480 <= 2^64 -> 0 <= tot < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (rs_eof_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 F fc lo tot P c pad7 pad2 g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz tot) (wz (P + O_H_EC)) a0 a1 a2 a3 a4 a5 a6 a7
             (wz P) (wz (P + O_H_FB)) (wz (P + O_H_STREAM)) (wz 0) s6x (wz G_MISC_CAT_INST) (wz G_SYSTEM_CAT_INST) (wz CAT_ID_SYSGEN_SHR1) s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 RS_CMP) fc None m (seg_rom rsegs)).

